export function createFoundationUI(ctx){
 const {state,api,apiBase,esc,icon,tag,date,title,blank,dialog,toast,refresh,isMember}=ctx;
 const roleNames={signaler:'Mission Signaler',coordinator:'Cycle Coordinator',auditor:'Audit Node',steward:'Governance steward',executor:'Accountable executor'};
 const sectors=['Community','Shared technology','Nexus Education','Champion Clinics','Saber Protect','Logistics & commerce'];
 const data=()=>state.foundation;
 const records=kind=>(data()?.records||[]).filter(r=>r.kind===kind);
 const now=()=>data()?.serverNow||Date.now()/1000;
 const live=r=>r.status==='active'&&r.expiresAt>now();
 const money=(amount,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format((amount||0)/100);
 const timestamp=t=>t?new Date(t*1000).toLocaleString():'Not yet recorded';
 const button=(action,label,id='',extra='')=>`<button class="btn btn-small" data-gaction="${action}" data-record-id="${esc(id)}" ${extra}>${esc(label)} ${icon('arrow')}</button>`;
 const fact=(key,value)=>`<div class="fact"><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`;
 const evidence=r=>`<details class="record-evidence"><summary>Evidence & record details</summary><dl class="facts">${Object.entries(r.payload).filter(([k])=>!['text','receipt','reason','scope','exclusions','digest'].includes(k)).map(([k,v])=>fact(k.replace(/([A-Z])/g,' $1').replace(/^./,s=>s.toUpperCase()),typeof v==='number'&&/At$|Until$|After$/.test(k)?timestamp(v):v)).join('')}</dl></details>`;
 const unavailable=()=>title('GOVERNANCE FOUNDATION','Connecting to the register','Charters, authority, appointments, and reviews are loaded from the Unison service.')+`<div class="notice">${icon('info')}The foundation register is unavailable. <button class="text-link" data-action="refresh">Try again</button></div>`;
 const summary=()=>{
  if(!data())return '';
  const adopted=records('charter').find(r=>r.status==='adopted');
  return `<section class="foundation-status ${adopted?'adopted':''}"><div>${icon(adopted?'shield':'book')}<div><strong>${adopted?'Charter adoption recorded':'Governance foundation · awaiting adoption'}</strong><p>${adopted?`${esc(adopted.payload.version)} · Authority remains limited to reviewed grants.`:'The founding charter is proposed. Authorized adoption and role appointments are required before new ballots can open.'}</p></div></div><a class="btn btn-small" href="#/charter">${adopted?'View charter':'Review the foundation'} ${icon('arrow')}</a></section>`;
 };
 const foundationNav=page=>`<nav class="foundation-tabs" aria-label="Governance foundation">${[['charter','Charter versions'],['authority','Authority register'],['roles','Roles & reviews'],['appeals','Appeals']].map(([id,label])=>`<a href="#/${id}" ${page===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
 function charter(selectedId){
  if(!data())return unavailable();
  const versions=records('charter');const r=versions.find(r=>r.id===selectedId)||versions.find(r=>r.status==='adopted')||versions[0];
  if(!r)return unavailable();
  const p=r.payload;
  const clauses=String(p.text).split(/\n\s*\n/).map((section,i)=>{const [heading,...lines]=section.split('\n');return i===0?`<p class="charter-document-title">${esc(section)}</p>`:`<section><h3>${esc(heading)}</h3><p>${esc(lines.join('\n'))}</p></section>`;}).join('');
  return `${title('SABER TECH / GOVERNANCE FOUNDATION','A charter with a recorded history.','Rights, responsibilities, decision rules, and the evidence of adoption.',data().canSteward?button('create-charter','Register new version'):'')}${foundationNav('charter')}${summary()}<div class="foundation-toolbar"><div class="version-links">${versions.map(v=>`<a class="btn btn-small ${v.id===r.id?'btn-light':''}" href="#/charter/${encodeURIComponent(v.id)}">${esc(v.payload.version)} · ${esc(v.status)}</a>`).join('')}</div><button class="text-link" data-gaction="export">Export public foundation ${icon('download')}</button></div><section class="panel"><div class="panel-head"><div><h2>${esc(p.version)}</h2><p>Immutable text and rule settings · ${esc(r.status==='adopted'?'Adoption attested and independently reviewed':r.status==='attested'?'Adoption evidence awaits independent review':r.status==='superseded'?'Retained historical version':'Proposed; no adoption has been recorded')}</p></div>${tag(r.status)}</div><div class="charter-rules">${[['Quorum',`${p.quorumPercent}% of electorate`],['Ordinary approval',`${p.ordinaryPercent}% of yes + no; yes must exceed no`],['Constitutional approval',`${p.constitutionalPercent}% of yes + no`],['Public notice',`${p.noticeDays} days`],['Voting window',`${p.votingDays} days`],['Challenge window',`${p.challengeHours} hours after finalization`]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="content-panel"><div class="button-row">${r.status==='draft'&&data().canSteward?button('attest-charter','Record adoption evidence',r.id):''}${r.status==='attested'&&data().canReview?button('adopt-charter','Independently review adoption',r.id):''}</div><p class="subtle" style="margin-top:13px">The service records authenticated attestations. The adopting body's authority and underlying decision must be established outside the software.</p>${evidence(r)}<details class="record-evidence"><summary>Version integrity reference</summary><p class="inline-code">SHA-256: ${esc(p.digest)}</p></details></div></section><article class="charter-document">${clauses}</article><section class="panel"><div class="content-panel"><h2>Establish the people before the powers.</h2><ol class="setup-list"><li>Approve a small, verified founding membership.</li><li>Nominate two independent Audit Nodes; each must accept the appointment.</li><li>Appoint stewards, coordinators, and executors with consent and independent review.</li><li>Record the authorized body's adoption evidence and an independent attestation.</li><li>Review an authority grant, then publish the first scoped proposal.</li></ol><p class="subtle">${data().bootstrapActive?`Temporary founding stewardship ends ${esc(timestamp(data().bootstrapEndsAt))}, or on adoption if earlier.`:'Founding bootstrap privileges are inactive.'}</p><div class="button-row"><a class="btn" href="#/roles">Roles & reviews ${icon('arrow')}</a><a class="btn" href="#/authority">Authority register ${icon('arrow')}</a></div></div></section>`;
 }
 function authority(){
  if(!data())return unavailable();
  const grants=records('grant');
  return `${title('SABER TECH / DELEGATED AUTHORITY','Make every mandate inspectable.','The issuer, limits, decision effect, and accountable executor for each grant.',data().canSteward?button('create-grant','Register authority grant'):'')}${foundationNav('authority')}${summary()}<div class="scope-note">${icon('info')}<p>Grants require an adopted charter and independent review. A budget ceiling limits a proposal's requested amount; it does not reserve funds or authorize a bank transfer.</p></div>${grants.length?`<div class="register-list">${grants.map(r=>{const p=r.payload;return `<section class="panel"><div class="panel-head"><div><div class="eyebrow">${esc(p.sector)} · ${esc(p.effect)} decision</div><h2>${esc(p.title)}</h2></div>${tag(r.status==='active'&&r.expiresAt<=now()?'expired':r.status)}</div><div class="content-panel"><p class="prose">${esc(p.scope)}</p><dl class="facts">${fact('Issuer',p.issuer)}${fact('Executor',r.targetName)}${fact('Per-proposal ceiling',money(p.ceilingMinor,p.currency))}${fact('Expires',timestamp(r.expiresAt))}${fact('Excluded authority',p.exclusions)}</dl>${evidence(r)}<div class="button-row">${data().canReview&&r.status==='proposed'?button('review-grant','Review authority',r.id):''}${data().canReview&&live(r)?button('revoke-grant','Record authorized revocation',r.id):''}</div></div></section>`;}).join('')}</div>`:blank('No authority grants recorded','After charter adoption, a steward can register a specific mandate for an appointed executor. An independent Audit Node reviews it before use.')}<div class="scope-note">${icon('shield')}<p>Corporate, academic, and clinical decisions retain their own authorities. Advisory decisions record advice. Joint decisions require additional approval evidence before execution review.</p></div>`;
 }
 function appointmentActions(r){
  let out='';const uid=state.user?.id;
  if(r.status==='nominated'&&r.target===uid)out+=button('accept-role','Accept appointment',r.id);
  if(r.status==='accepted'&&data().canReview)out+=button('review-role','Review appointment',r.id);
  if(live(r)&&(r.target===uid||data().canReview))out+=button('end-role',r.target===uid?'Resign appointment':'Record removal',r.id);
  if(live(r)&&data().canSteward)out+=button('nominate','Nominate renewal',r.id);
  return out;
 }
 function roles(){
  if(!data())return unavailable();
  const appointments=records('appointment'),executions=records('execution');
  return `${title('SABER TECH / ACCOUNTABLE ROLES','Named people. Limited powers.','Appointments have a scope, consent, an expiry, and a review record.',data().canSteward?button('nominate','Nominate a role holder'):'')}${foundationNav('roles')}<div class="roles-panel"><div class="roles-grid">${[['signaler','Develop needs and proposals. All active members may draft.'],['coordinator','Administer notice, voting, and follow-through within a sector.'],['auditor','Review authority, appeals, and execution independently.'],['steward','Manage eligibility, charter records, and nominations.'],['executor','Deliver the authorized action and submit evidence.']].map(([k,d])=>`<div><h3>${roleNames[k]}</h3><p>${d}</p></div>`).join('')}</div><p class="subtle">Audit Nodes cannot simultaneously hold operational appointments. Self-review is blocked by the service. Founding stewardship is temporary; appoint successors before adoption or expiry.</p></div>${appointments.length?`<section class="panel"><div class="panel-head"><h2>Appointment register</h2></div>${appointments.map(r=>`<div class="register-row"><div class="register-row-heading"><div><h3>${esc(r.targetName)} · ${esc(roleNames[r.payload.role]||r.payload.role)}</h3><p class="subtle">${esc(r.payload.sector)} · Until ${esc(timestamp(r.expiresAt))}</p></div>${tag(['active','accepted','nominated'].includes(r.status)&&r.expiresAt<=now()?'expired':r.status)}</div><p class="subtle">${esc(r.payload.reason)}</p>${evidence(r)}<div class="button-row">${appointmentActions(r)}</div></div>`).join('')}</section>`:blank('No appointments recorded','The founding steward can nominate the initial independent reviewers. Nominees must sign in and accept before their role becomes active.')}<section class="panel"><div class="panel-head"><div><h2>Execution review</h2><p>Submission and independent acceptance are separate records.</p></div>${icon('checkCircle')}</div>${executions.length?executions.map(r=>`<div class="register-row"><div class="register-row-heading"><a class="text-link" href="#/proposal/${encodeURIComponent(r.target)}">Proposal ${esc(r.target.slice(0,8))} ${icon('arrow')}</a>${tag(r.status)}</div><p class="prose">${esc(r.payload.receipt)}</p><p class="subtle">Submitted by ${esc(r.actorName)}</p>${evidence(r)}${data().canReview&&r.status==='pending'?`<div class="button-row">${button('review-execution','Review execution evidence',r.id)}</div>`:''}</div>`).join(''):blank('No execution receipts awaiting review','After approval and the challenge window, the appointed executor can submit evidence from the proposal page.')}</section>${auditTrail()}`;
 }
 function auditTrail(){return `<section class="panel"><div class="panel-head"><div><h2>Foundation activity</h2><p>Recent service records; export copies for independent retention.</p></div><button class="text-link" data-gaction="export">Export ${icon('download')}</button></div>${(data()?.audit||[]).length?data().audit.slice(0,30).map(r=>`<div class="activity-item"><i class="activity-dot"></i><div><p>${esc(r.payload.action.replaceAll('-',' '))} · ${esc(r.actorName)}</p><time>${esc(timestamp(r.createdAt))}</time></div></div>`).join(''):'<p class="empty-inline">The first recorded governance action will appear here.</p>'}</section>`;}
 function appeals(){
  if(!data())return unavailable();
  const appeals=records('appeal');
  return `${title('SABER TECH / DUE PROCESS','A decision can be challenged.','Recorded grounds, independent review, and a reasoned outcome.',state.user&&state.user.status!=='visitor'?button('appeal','Appeal my membership'):'')}${foundationNav('appeals')}<div class="scope-note">${icon('lock')}<p>Membership appeal grounds are restricted to the appellant and Audit Nodes. Proposal challenges are public and filed from the proposal during its challenge window. Open proposal appeals block execution.</p></div>${appeals.length?appeals.map(r=>`<section class="panel"><div class="panel-head"><div><div class="eyebrow">${r.payload.targetType==='membership'?'RESTRICTED MEMBERSHIP CASE':'PUBLIC PROPOSAL CHALLENGE'}</div><h2>Appeal ${esc(r.id.slice(0,8))}</h2><p>Filed ${esc(timestamp(r.createdAt))} · ${esc(r.actorName)}</p></div>${tag(r.status)}</div><div class="content-panel"><h3>Grounds & requested correction</h3><p class="prose" style="margin-top:10px">${esc(r.payload.reason)}</p>${r.payload.resolution?`<h3 style="margin-top:20px">Review outcome</h3><p class="prose">${esc(r.payload.resolution)}</p>`:''}${evidence(r)}<div class="button-row">${r.payload.proposalId?`<a class="btn btn-small" href="#/proposal/${encodeURIComponent(r.payload.proposalId)}">View proposal ${icon('arrow')}</a>`:''}${r.status==='open'&&data().canReview?button('review-appeal','Review appeal',r.id):''}</div></div></section>`).join(''):blank('No appeals visible to you','Sign in to see your membership cases. Published proposal challenges appear here when filed.')}`;
 }
 const field=(label,name,{value='',type='text',min='',max='',required=true,help='',options}={})=>`<label class="field field-full">${esc(label)}${options?`<select aria-label="${esc(label)}" name="${name}" ${required?'required':''}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea aria-label="${esc(label)}" name="${name}" ${required?'required':''} ${min?`minlength="${min}"`:''} ${max?`maxlength="${max}"`:''}>${esc(value)}</textarea>`:`<input aria-label="${esc(label)}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${min?`${type==='number'?'min':'minlength'}="${min}"`:''} ${max?`${type==='number'?'max':'maxlength'}="${max}"`:''} ${type==='number'?'step="1"':''}>`}${help?`<small>${esc(help)}</small>`:''}</label>`;
 async function form(action,id='',proposalId=''){
  const r=data()?.records.find(x=>x.id===id),current=records('charter').find(x=>x.status==='adopted')||records('charter')[0];
  let heading='',intro='',fields='',ack='I have checked the authority, accuracy, and intended visibility of this record.';
  if(action==='nominate'){
   const roster=(await api('/members')).members.filter(m=>m.status==='active');
   heading='Nominate a role holder';intro='The nominee must accept. Appointments require independent review, except the first two provisional Audit Nodes during founding setup.';
   fields=field('Approved member','memberId',{value:r?.target||'',options:roster.map(m=>[m.id,`${m.name} (@${m.login})`])})+field('Role','role',{value:r?.payload.role||'',options:Object.entries(roleNames)})+field('Scope','sector',{value:r?.payload.sector||'All',options:['All',...sectors],help:'Stewards and Audit Nodes use All. Other roles may cover one sector or the whole community.'})+field('Term (days)','termDays',{type:'number',value:90,min:1,max:90})+field('Appointment reason and authority','reason',{type:'textarea',min:20,max:2000});
  }else if(action==='accept-role'){
   heading='Accept appointment';intro=`Accept ${roleNames[r?.payload.role]||'this role'} for ${r?.payload.sector}, until ${timestamp(r?.expiresAt)}. Your accepted role and its evidence become public.`;ack='I accept these responsibilities and the published term. I understand that this role does not add voting weight.';
  }else if(action==='end-role'){
   heading='End appointment';intro='Record resignation or an authorized removal. The last appointed steward needs an active successor.';fields=field('Reason and authority','reason',{type:'textarea',min:20,max:2000});
  }else if(action==='create-charter'){
   heading='Register a new charter version';intro='This creates an immutable proposal, not an adoption. Review the text and structured rules together.';
   fields=field('Version label','version',{min:4,max:60})+field('Complete charter text','text',{type:'textarea',value:current?.payload.text||'',min:500,max:16000})+[['Quorum (%)','quorumPercent',1,100],['Ordinary approval (%)','ordinaryPercent',50,100],['Constitutional approval (%)','constitutionalPercent',50,100],['Public notice (days)','noticeDays',1,30],['Voting window (days)','votingDays',1,30],['Challenge period (hours)','challengeHours',24,336]].map(([label,name,min,max])=>field(label,name,{type:'number',value:current?.payload[name],min,max})).join('');
  }else if(action==='attest-charter'){
   heading='Record charter adoption evidence';intro=`Identify the authorized body's decision adopting ${r?.payload.version}. An independent Audit Node must verify this record before the app treats the charter as adopted.`;fields=field('Adopting body','body',{min:3,max:160})+field('Decision reference and adoption evidence','evidence',{type:'textarea',min:40,max:3000});ack='This exact charter version and its structured rules were adopted by the identified authorized body. I have retained the source decision.';
  }else if(action==='create-grant'){
   const executors=records('appointment').filter(x=>live(x)&&x.payload.role==='executor');
   heading='Register an authority grant';intro='State the exact mandate delegated by an authorized issuer. A reviewer must verify the source evidence before the grant can be used.';
   fields=field('Grant title','title',{min:5,max:160})+field('Issuing body','issuer',{min:3,max:160})+field('Sector','sector',{options:sectors})+field('Decision effect','effect',{options:[['advisory','Advisory — record advice'],['binding','Binding within the recorded mandate'],['joint','Requires additional joint approval']]})+field('Appointed executor','executorId',{options:executors.map(x=>[x.target,`${x.targetName} · ${x.payload.sector}`]),help:executors.length?'The appointment must cover the selected sector.':'Appoint an executor in Roles & reviews first.'})+field('Delegation evidence','evidence',{type:'textarea',min:40,max:3000})+field('Exact scope','scope',{type:'textarea',min:40,max:3000})+field('Excluded authority','exclusions',{type:'textarea',min:20,max:2000})+field('Currency','currency',{options:['USD','CAD','EUR','GBP']})+field('Per-proposal ceiling (minor units / cents)','ceilingMinor',{type:'number',value:0,min:0,max:100000000,help:'100 cents = 1 currency unit. Use 0 for a non-financial mandate. This does not reserve funds.'})+field('Valid for (days)','validDays',{type:'number',value:90,min:1,max:365});
  }else if(action==='notice'){
   const proposal=await api('/proposals/'+encodeURIComponent(proposalId));
   const grants=records('grant').filter(x=>live(x)&&x.payload.sector===proposal.sector);
   heading='Publish a governed notice';intro='The selected grant, charter version, decision rules, amount, and executor become fixed. Voting opens after the adopted notice period.';
   fields=field('Reviewed authority grant','grantId',{options:grants.map(x=>[x.id,`${x.payload.title} · ${x.payload.effect}`]),help:grants.length?'':'No current grant exists for this sector. Complete the authority register first.'})+field('Adopted rule set','ruleSet',{options:[['ordinary','Ordinary decision'],['constitutional','Constitutional decision']]})+field('Requested amount (minor units / cents)','amountMinor',{type:'number',value:0,min:0,max:100000000,help:'Use the grant currency. 100 cents = 1 currency unit. Amount must fit the grant ceiling.'});
   ack='I have reviewed the proposal against the recorded mandate and the affected community. This text may be published.';
  }else if(action==='open'){
   heading='Open the published ballot';intro='The service will check the notice deadline, current authority, and executor appointment, then freeze the electorate. The adopted rule set cannot be overridden.';
  }else if(action==='submit-execution'){
   heading='Submit execution evidence';intro='Only the named executor may submit after the challenge period and resolution of appeals. An independent Audit Node must accept the evidence before completion is recorded.';
   fields=field('Public action receipt','receipt',{type:'textarea',min:40,max:4000})+field('Additional joint-approval evidence','jointEvidence',{type:'textarea',required:false,max:2000,help:'Required for a joint-approval grant. Include the authorizing body and exact decision reference.'});
  }else if(action==='appeal'){
   heading=proposalId?'Challenge this proposal':'Appeal my membership';intro=proposalId?'State the procedural or authority problem and requested correction. This challenge is public and blocks execution while unresolved.':'State the membership decision, grounds, and requested correction. Your grounds are visible to you and authorized Audit Nodes.';
   fields=`<input type="hidden" name="targetType" value="${proposalId?'proposal':'membership'}">`+field('Grounds and requested correction','reason',{type:'textarea',min:40,max:3000});
  }else{
   const labels={'review-role':'Review appointment','adopt-charter':'Verify charter adoption','review-grant':'Verify delegated authority','revoke-grant':'Record authorized revocation','review-appeal':'Resolve appeal','review-execution':'Review execution evidence'};
   heading=labels[action];if(!heading)throw new Error('Unknown governance action.');
   intro='Review the underlying evidence and your independence. A title or an application permission does not establish legal authority. Your evidence and conflict disclosure will be retained with the record.';
   if(action==='review-appeal')fields+=field('Outcome','outcome',{options:[['dismissed','Dismiss — explain why the decision stands'],['upheld','Uphold — restore membership or require a new proposal']]});
   if(action==='review-execution')fields+=field('Outcome','outcome',{options:[['accepted','Accept evidence and record completion'],['rejected','Reject evidence; executor may submit a corrected receipt']]});
   fields+=field('Review evidence and reasons','evidence',{type:'textarea',min:40,max:3000})+field('Conflict-of-interest disclosure','conflicts',{type:'textarea',min:4,max:1000,help:'Declare relevant interests. If none, state that. Recuse rather than submit if you cannot review independently.'});ack='I am authorized and independent of this decision. I have disclosed relevant interests and verified the supporting record.';
  }
  dialog(heading,`<p>${esc(intro)}</p><form id="foundation-form" data-operation="${action}" data-id="${esc(id)}" data-proposal-id="${esc(proposalId)}"><div class="form-grid">${fields}</div><label class="checkbox"><input type="checkbox" required>${esc(ack)}</label><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">${esc(action==='accept-role'?'Accept appointment':'Save record')} ${icon('check')}</button></div></form>`);
 }
 async function exportPublic(){
  const response=await fetch(`${apiBase}/api/foundation`,{credentials:'omit',headers:{Accept:'application/json'}});
  if(!response.ok)throw new Error('The public foundation export is unavailable.');
  const payload={format:'axiom-public-foundation-v1',exportedAt:new Date().toISOString(),foundation:await response.json()};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='saber-tech-public-foundation.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Public foundation exported. Retain a copy with an independent custodian.');
 }
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-gaction]');if(!el)return;e.preventDefault();try{if(el.dataset.gaction==='export')await exportPublic();else await form(el.dataset.gaction,el.dataset.recordId||'',el.dataset.proposalId||'');}catch(error){toast(error.message);}});
 document.addEventListener('submit',async e=>{
  const formEl=e.target;if(formEl.id!=='foundation-form')return;e.preventDefault();
  const submit=formEl.querySelector('button:not([type="button"])'),err=formEl.querySelector('.form-error');submit.disabled=true;err.textContent='';
  const payload=Object.fromEntries(new FormData(formEl));if(formEl.dataset.id)payload.id=formEl.dataset.id;if(formEl.dataset.proposalId)payload.proposalId=formEl.dataset.proposalId;
  for(const k of ['termDays','quorumPercent','ordinaryPercent','constitutionalPercent','noticeDays','votingDays','challengeHours','ceilingMinor','amountMinor','validDays'])if(k in payload)payload[k]=Number(payload[k]);
  try{await api('/foundation/'+formEl.dataset.operation,{method:'POST',body:JSON.stringify(payload)});document.querySelector('#modal').close();toast('Governance record saved.');await refresh();}catch(error){err.textContent=error.message;submit.disabled=false;}
 });
 function proposalPanel(p){
  const publication=p.governance,meta=publication?.payload;
  const canAppeal=state.user&&p.canChallenge;
  let actions='';
  if(p.canCoordinate&&p.status==='notice')actions+=button('open','Open voting','',`data-proposal-id="${esc(p.id)}" ${p.serverNow<meta.opensAfter?'disabled':''}`);
  if(p.executionReady&&state.user?.id===meta?.executorId)actions+=button('submit-execution','Submit execution evidence','',`data-proposal-id="${esc(p.id)}"`);
  if(canAppeal)actions+=button('appeal','Challenge this proposal','',`data-proposal-id="${esc(p.id)}"`);
  return `<section class="panel"><div class="panel-head"><h2>Authority & independent review</h2>${icon('shield')}</div><div class="content-panel">${meta?`<dl class="facts">${fact('Charter',meta.charterVersion)}${fact('Rule set',meta.ruleSet)}${fact('Decision effect',meta.effect)}${fact('Requested amount',money(meta.amountMinor,meta.currency))}${fact('Voting may open after',timestamp(meta.opensAfter))}${fact('Challenge window ends',timestamp(meta.challengeUntil))}</dl><a class="text-link" href="#/authority">Inspect the authority register ${icon('arrow')}</a>`:'<p class="subtle">This draft needs an adopted charter, a current authority grant, and a Cycle Coordinator before public notice.</p>'}<div class="button-row">${actions}</div>${(p.reviewRecords||[]).map(r=>`<div class="proposal-review-record"><div class="register-row-heading"><h3>${r.kind==='appeal'?'Proposal challenge':'Execution receipt'}</h3>${tag(r.status)}</div><p class="prose">${esc(r.payload.reason||r.payload.receipt)}</p>${r.payload.resolution?`<p class="subtle">${esc(r.payload.resolution)}</p>`:''}${evidence(r)}${p.canReview&&((r.kind==='appeal'&&r.status==='open')||(r.kind==='execution'&&r.status==='pending'))?`<div class="button-row">${button(r.kind==='appeal'?'review-appeal':'review-execution','Review record',r.id)}</div>`:''}</div>`).join('')}</div></section>`;
 }
 return {charter,authority,roles,appeals,summary,form,proposalPanel};
}
